class UArenaHud;
class UArenaPalette;
class UArenaScoreTracker;
struct FArenaStats;

UCLASS()
class PIXELARENA_API AArenaGameMode : public AGameModeBase
{
	GENERATED_BODY()

public:
	virtual void BeginPlay() override;
	virtual void EndPlay(const EEndPlayReason::Type Reason) override;

	void OnGoalScored(int32 TeamIndex);

private:
	UPROPERTY()
	TObjectPtr<UArenaHud> Hud;

	UPROPERTY()
	TObjectPtr<UArenaPalette> Palette;

	UPROPERTY() TObjectPtr<UArenaScoreTracker> ScoreTracker = nullptr;

	// Plain C++ data owned by this class, freed in EndPlay.
	FArenaStats* Stats = nullptr;
};


--- result.json ---
{"crash_cause":"UArenaScoreTracker is a UObject held in a raw pointer member (not UPROPERTY), so the garbage collector purged it (LogGarbage, 412 objects) and OnGoalScored dereferenced it -> EXCEPTION_ACCESS_VIOLATION in UArenaScoreTracker::AddPoints (ArenaGameMode.cpp:38). Fixed by declaring ScoreTracker as UPROPERTY TObjectPtr<UArenaScoreTracker>.","no_colors_cause":"Cooking is selective (bCookAll=False) and only Effects was listed in DirectoriesToAlwaysCook, so /Game/Data/Palettes/DA_Primary (and the ArenaPalette asset) was never cooked; LoadObject returned nullptr, palette fallback to gray. Fixed by adding +DirectoriesToAlwaysCook=(Path=\"/Game/Data/Palettes\") to Config/DefaultGame.ini."}
